import torch
import torch.nn as nn
import torch.nn.functional as F
import math
import os
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# HIP kernel for fused causal attention
# This kernel will handle the q@k, scaling, causal masking, softmax, and attn@v
# for a single head.
# B: batch size, H: number of heads, T: sequence length, D: head size

attention_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>
#include <hip/hip_fp16.h>

__global__ void fused_causal_attention_kernel(
    const float* __restrict__ q, // (B, H, T, D)
    const float* __restrict__ k, // (B, H, T, D)
    const float* __restrict__ v, // (B, H, T, D)
    float* __restrict__ out,      // (B, H, T, D)
    int B, int H, int T, int D,
    float scale)
{
    // Each block handles one head of one batch: (batch, head, row_of_Q)
    int b = blockIdx.x;
    int h = blockIdx.y;
    int t = blockIdx.z; // row of Q

    if (b >= B || h >= H || t >= T) return;

    // Offsets
    int head_offset = (b * H + h) * T * D;
    const float* q_ptr = q + head_offset + t * D;
    const float* k_ptr = k + head_offset;
    const float* v_ptr = v + head_offset;
    float* out_ptr = out + head_offset + t * D;

    // We need to compute:
    // row_att[j] = exp( (q[t] * k[j]) * scale ) for j <= t
    // row_att[j] = 0 for j > t
    // out[t] = sum(row_att[j] * v[j]) / sum(row_att[j])

    // For better performance, we can use a small shared memory buffer or just registers.
    // Given D=96, it's small enough to keep in registers.

    float max_val = -1e20f;

    // We'll store the dot products in a local array (in registers if T is small)
    // But T=512 is a bit large for registers. Let's use a two-pass approach.

    // First pass: find max_val and compute dot products
    // We can use a small buffer in shared memory.
    extern __shared__ float shared_mem[];
    float* dot_products = shared_mem; // T floats

    for (int j = 0; j <= t; ++j) {
        float sum = 0.0f;
        for (int d = 0; d < D; ++d) {
            sum += q_ptr[d] * k_ptr[j * D + d];
        }
        sum *= scale;
        dot_products[j] = sum;
        if (sum > max_val) max_val = sum;
    }

    // Second pass: compute sum of exps
    float exp_sum = 0.0f;
    for (int j = 0; j <= t; ++j) {
        dot_products[j] = expf(dot_products[j] - max_val);
        exp_sum += dot_products[j];
    }

    // Third pass: compute weighted sum of v
    for (int d = 0; d < D; ++d) {
        float out_val = 0.0f;
        for (int j = 0; j <= t; ++j) {
            out_val += dot_products[j] * v_ptr[j * D + d];
        }
        out_ptr[d] = out_val / exp_sum;
    }
}

torch::Tensor fused_causal_attention_hip(torch::Tensor q, torch::Tensor k, torch::Tensor v, float scale) {
    int B = q.size(0);
    int H = q.size(1);
    int T = q.size(2);
    int D = q.size(3);

    auto out = torch::empty_like(q);

    dim3 grid(B, H, T);
    dim3 block(1); // One thread per row for simplicity initially, though not optimal

    // Each block needs T * sizeof(float) shared memory
    size_t shared_mem_size = T * sizeof(float);

    fused_causal_attention_kernel<<<grid, block, shared_mem_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        out.data_ptr<float>(),
        B, H, T, D,
        scale
    );

    return out;
}
"""

attention_lib = load_inline(
    name="attention_lib",
    cpp_sources=attention_kernel_source,
    functions=["fused_causal_attention_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.n_head = n_head
        self.n_embd = n_embd
        self.scale = 1.0 / math.sqrt(n_embd // n_head)

    def forward(self, x):
        B, T, C = x.size()

        # Linear layer and split
        qkv = self.c_attn(x)
        q, k, v = qkv.split(self.n_embd, dim=2)

        # Reshape for multi-head attention
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()

        # Custom fused attention kernel
        y = attention_lib.fused_causal_attention_hip(q, k, v, self.scale)

        # Reshape and project back
        y = y.transpose(1, 2).contiguous().view(B, T, C)
        y = self.resid_dropout(self.c_proj(y))
        return y

