__global__ void split_qkv_bias_kernel(
    const float* __restrict__ qkv,
    const float* __restrict__ bias,
    float* __restrict__ q,
    float* __restrict__ k,
    float* __restrict__ v,
    int B, int T, int H, int D) 
{
    int b = blockIdx.z;
    int t = blockIdx.y * blockDim.y + threadIdx.y;
    int h = (blockIdx.x * blockDim.x + threadIdx.x) / D;
    int d = (blockIdx.x * blockDim.x + threadIdx.x) % D;

    if (t < T && h < H && d < D) {
        int C = H * D;
        int qkv_idx_base = b * T * 3 * C + t * 3 * C;
        int out_idx = b * H * T * D + h * T * D + t * D + d;

        q[out_idx] = qkv[qkv_idx_base + 0 * C + h * D + d] + bias[0 * C + h * D + d];
        k[out_idx] = qkv[qkv_idx_base + 1 * C + h * D + d] + bias[1 * C + h * D + d];
        v[out_idx] = qkv[qkv_idx_base + 2 * C + h * D + d] + bias[2 * C + h * D + d];
    }
}

std::vector<torch::Tensor> split_qkv_bias_hip(torch::Tensor qkv, torch::Tensor bias, int H, int D) {
    int B = qkv.size(0);
    int T = qkv.size(1);

    auto q = torch::empty({B, H, T, D}, qkv.options());
    auto k = torch::empty({B, H, T, D}, qkv.options());
    auto v = torch::empty({B, H, T, D}, qkv.options());

    dim3 block(128, 8);
    dim3 grid(((H * D) + 127) / 128, (T + 7) / 8, B);

    split_qkv_bias_kernel<<<grid, block>>>(
        qkv.data_ptr<float>(), bias.data_ptr<float>(),
        q.data_ptr<float>(), k.data_ptr<float>(), v.data_ptr<float>(),
        B, T, H, D
    );
    return {q, k, v};
}

__global__ void fused_bias_add_kernel(float* x, const float* bias, int B, int T, int C) {
    int b = blockIdx.z;
    int t = blockIdx.y * blockDim.y + threadIdx.y;
    int c = blockIdx.x * blockDim.x + threadIdx.x;

    if (t < T && c < C) {
        x[b * T * C + t * C + c] += bias[c];
    }
}

torch::Tensor fused_bias_add_hip(torch::Tensor x, torch::Tensor bias) {
    int B = x.size(0);
    int T = x.size(1);
    int C = x.size(2);
    dim3 block(32, 32);
    dim3 grid((C + 31) / 32, (T + 31) / 32, B);
    fused_bias_add_kernel<<<grid, block>>>(x.data_ptr<float>(), bias.data_ptr<float>(), B, T, C);
    return x;
}
